component MeshBackground {
  ref canvas
  ref animationFrame

  mount {
    let w = canvas.width = canvas.offsetWidth * devicePixelRatio
    let h = canvas.height = canvas.offsetHeight * devicePixelRatio
    let ctx = canvas.getContext("2d")
    let time = 0

    fn draw() {
      ctx.fillStyle = "url(#grad)"
      let grad = ctx.createLinearGradient(0, 0, w, h)
      grad.addColorStop(0, `hsl(${200 + Math.sin(time * 0.0005) * 20}, 70%, 60%)`)
      grad.addColorStop(0.5, `hsl(${280 + Math.sin(time * 0.0003) * 20}, 60%, 50%)`)
      grad.addColorStop(1, `hsl(${0 + Math.sin(time * 0.0004) * 20}, 80%, 55%)`)
      ctx.fillStyle = grad
      ctx.fillRect(0, 0, w, h)

      for (let i = 0; i < 50; i++) {
        let x = (Math.sin(i + time * 0.0001) + 1) * w / 2
        let y = (Math.cos(i * 0.7 + time * 0.00008) + 1) * h / 2
        let size = 50 + Math.sin(time * 0.0002 + i) * 30
        ctx.fillStyle = `rgba(255, 255, 255, ${0.05 + Math.sin(time * 0.0003 + i) * 0.03})`
        ctx.beginPath()
        ctx.arc(x, y, size, 0, Math.PI * 2)
        ctx.fill()
      }

      time++
      animationFrame = requestAnimationFrame(draw)
    }

    draw()
    cleanup {
      cancelAnimationFrame(animationFrame)
    }
  }

  canvas width=800 height=600 style="position: absolute; top: 0; left: 0; width: 100%; height: 100%;"
}

component Counter(target: Number) {
  state current = 0
  ref started = false

  effect {
    if !started {
      started = true
      let prefersReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches
      let duration = prefersReduced ? 0 : 2000
      let start = Date.now()

      fn update() {
        let elapsed = Date.now() - start
        if elapsed >= duration {
          current = target
        } else {
          current = Math.floor((elapsed / duration) * target)
          requestAnimationFrame(update)
        }
      }

      if duration > 0 {
        requestAnimationFrame(update)
      } else {
        current = target
      }
    }
  }

  text `${current.toLocaleString()}`
}

