component MeshBackground {
  ref canvas
  state time = 0

  mount {
    let ctx = canvas.getContext("2d")
    let width = canvas.width
    let height = canvas.height

    let animate = () => {
      time += 0.005
      ctx.fillStyle = `hsl(${210 + Math.sin(time) * 10}, 70%, 50%)`
      ctx.fillRect(0, 0, width, height)

      let gradient = ctx.createLinearGradient(0, 0, width, height)
      gradient.addColorStop(0, `hsl(${240 + Math.sin(time) * 20}, 80%, 60%)`)
      gradient.addColorStop(0.5, `hsl(${220 + Math.cos(time * 0.7) * 15}, 75%, 55%)`)
      gradient.addColorStop(1, `hsl(${200 + Math.sin(time * 0.5) * 25}, 85%, 50%)`)

      ctx.fillStyle = gradient
      ctx.fillRect(0, 0, width, height)

      for (let i = 0; i < 5; i++) {
        ctx.strokeStyle = `rgba(255, 255, 255, ${0.1 + Math.sin(time + i) * 0.05})`
        ctx.lineWidth = 2
        ctx.beginPath()
        ctx.arc(
          Math.sin(time * 0.3 + i) * width * 0.5 + width * 0.5,
          Math.cos(time * 0.25 + i) * height * 0.4 + height * 0.5,
          100 + Math.sin(time + i * 0.5) * 50,
          0,
          Math.PI * 2
        )
        ctx.stroke()
      }

      requestAnimationFrame(animate)
    }
    animate()

    cleanup {
      cancelAnimationFrame(animate)
    }
  }

  canvas width=1920 height=1080 style="position: absolute; top: 0; left: 0; width: 100%; height: 100%;"
}

component Counter {
  ref ref
  state count = 0
  state mounted = false

  mount {
    mounted = true
    let target = 12000
    let duration = 2000
    let start = Date.now()

    let prefersReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    let actualDuration = prefersReduced ? 0 : duration

    let animate = () => {
      let elapsed = Date.now() - start
      let progress = Math.min(elapsed / actualDuration, 1)

      let easeOut = 1 - Math.pow(1 - progress, 3)
      count = Math.floor(target * easeOut)

      if progress < 1 {
        requestAnimationFrame(animate)
      }
    }

    if actualDuration > 0 {
      animate()
    } else {
      count = target
    }

    cleanup { }
  }

  column align=center gap=2 {
    title `${count.toLocaleString()}+` tag=h2 style="font-size: 4rem; font-weight: 900; margin: 0;"
    text "Usuarios activos" muted
  }
}

