import { createSignal, createEffect, onMount } from 'solid-js';
import './UserCounter.css';

export default function UserCounter() {
  const [count, setCount] = createSignal(0);
  const [isVisible, setIsVisible] = createSignal(false);
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  onMount(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !isVisible()) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.5 }
    );

    const element = document.getElementById('user-counter');
    if (element) {
      observer.observe(element);
    }
  });

  createEffect(() => {
    if (!isVisible()) return;

    if (prefersReducedMotion) {
      setCount(12000);
      return;
    }

    const target = 12000;
    const duration = 2000;
    const startTime = Date.now();

    const animate = () => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);

      // Easing function for smooth animation
      const easeOutQuad = 1 - Math.pow(1 - progress, 2);
      const currentCount = Math.floor(easeOutQuad * target);

      setCount(currentCount);

      if (progress < 1) {
        requestAnimationFrame(animate);
      }
    };

    animate();
  });

  return (
    <section class="py-24 px-4 bg-gray-900 border-t border-gray-700">
      <div class="max-w-4xl mx-auto text-center">
        <div 
          id="user-counter"
          class="counter-section"
        >
          <div class="text-6xl md:text-8xl font-bold mb-4 bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text text-transparent">
