import { createSignal, onMount } from 'solid-js';

interface CardProps {
  title: string;
  description: string;
  index: number;
  prefersReducedMotion: boolean;
}

export default function Card(props: CardProps) {
  const [isVisible, setIsVisible] = createSignal(false);

  onMount(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            if (props.prefersReducedMotion) {
              setIsVisible(true);
            } else {
              setTimeout(() => setIsVisible(true), props.index * 200);
            }
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.1 }
    );

    const element = document.getElementById(`card-${props.index}`);
    if (element) observer.observe(element);
  });

  return (
    <div
      id={`card-${props.index}`}
      class={`bg-slate-900 p-8 rounded-lg border border-slate-800 transition-all duration-700 ${
        isVisible()
          ? 'opacity-100 translate-y-0'
          : 'opacity-0 translate-y-10'
      }`}
    >
      <h3 class="text-2xl font-bold text-white mb-3">{props.title}</h3>
      <p class="text-slate-400">{props.description}</p>
    </div>
  );
}

